import re


def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not s:
        raise ValueError("Empty string")

    # 1. Character validation (uppercase only, valid Roman chars)
    if not re.fullmatch(r'[IVXLCDM]+', s):
        raise ValueError("Invalid characters")

    # 2. Structural validation using a strict regular expression for valid Roman numerals
    # This regex enforces:
    # - M{0,3}
    # - CM|CD|D?C{0,3}
    # - XC|XL|L?X{0,3}
    # - IX|IV|V?I{0,3}
    pattern = r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$'
    if not re.fullmatch(pattern, s):
        raise ValueError("Invalid Roman numeral structure")

    # 3. Conversion
    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev = 0
    for char in reversed(s):
        val = values[char]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val

    return total
